def enforce(flow):
    if flow.get("dst_label") == "public-ingress":
        return "allow"

    if flow.get("src_segment") == "payroll" and flow.get("dst_segment") == "analytics":
        return "deny"

    return "allow"

def enforce(flow):
    if flow.get("protocol") == "tcp" and flow.get("src_ns") == "payments" and flow.get("dst_ns") == "ledger" and flow.get("dst_port") == 8443 and flow.get("src_label") == "role=settlement" and flow.get("dst_label") == "tier=write-api":
        return "allow"
    return "deny"

def enforce(flow, quarantined_ids):
    if flow.get("src_id") in quarantined_ids:
        if (
            flow.get("dst_id") == "containment-sink"
            and flow.get("protocol") == "tcp"
            and flow.get("dst_port") == 9443
        ):
            return "allow"
        return "isolate"

    if flow.get("src_zone") == "restricted" and flow.get("dst_zone") == "corporate":
        return "deny"
    return "allow"
